package com.nivor.project;
import com.nivor.common.exception.ResourceNotFoundException;import com.nivor.project.dto.ProjectRequest;import com.nivor.task.TaskRepository;import com.nivor.user.*;import com.nivor.workspace.*;import com.nivor.file.FileAssetRepository;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ProjectService{
private final ProjectRepository projects;private final WorkspaceRepository workspaces;private final TaskRepository tasks;private final UserService users;private final FileAssetRepository files;public ProjectService(ProjectRepository p,WorkspaceRepository w,TaskRepository t,UserService u,FileAssetRepository f){projects=p;workspaces=w;tasks=t;users=u;files=f;}
@Transactional(readOnly=true)public List<Project> list(String email,Long workspaceId,ProjectStatus status){Long uid=users.getByEmail(email).getId();return (workspaceId==null?projects.findAllByUser_IdOrderByDeadlineAsc(uid):projects.findAllByUser_IdAndWorkspace_Id(uid,workspaceId)).stream().filter(p->status==null||p.getStatus()==status).toList();}@Transactional(readOnly=true)public Project get(String email,Long id){return owned(email,id);}@Transactional public Project create(String email,ProjectRequest r){Project p=new Project();p.setUser(users.getByEmail(email));apply(p,r);return projects.save(p);}@Transactional public Project update(String email,Long id,ProjectRequest r){Project p=owned(email,id);apply(p,r);return p;}@Transactional public void delete(String email,Long id){Project p=owned(email,id);tasks.clearProjectForUser(p.getId(),p.getUser().getId());files.clearProjectForUser(p.getId(),p.getUser().getId());projects.delete(p);}
private Project owned(String email,Long id){return projects.findByIdAndUser_Id(id,users.getByEmail(email).getId()).orElseThrow(()->new ResourceNotFoundException("Project not found"));}private void apply(Project p,ProjectRequest r){p.setName(r.name().trim());p.setDescription(r.description());p.setStatus(r.status()==null?ProjectStatus.PLANNED:r.status());p.setProgress(r.progress());p.setDeadline(r.deadline());p.setWorkspace(r.workspaceId()==null?null:workspaces.findByIdAndUser_Id(r.workspaceId(),p.getUser().getId()).orElseThrow(()->new ResourceNotFoundException("Workspace not found")));}
}
